def shortest_subarray(nums, k):
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    best = float('inf')
    for i in range(n + 1):
        for j in range(i):
            if prefix[i] - prefix[j] >= k:
                best = min(best, i - j)

    return best if best != float('inf') else -1


